import { createContext, createMemo, createSignal, useContext } from "solid-js";
import { invariant } from "./utils.js";

export const RouterContext = createContext();

// Like the real router's useOptionalContext: the exact parameter's every
// reference is solely a context read. This neither provides nor patches it.
export function optionalContext(context) {
  try {
    return useContext(context);
  } catch {
    return undefined;
  }
}
export function isMounted() {
  return !!optionalContext(RouterContext);
}

// The @solidjs/router 2.0.0-next.26 shape: a hook reads the context through
// an identity guard, and another projects one member of the value.
export const useRouter = () => invariant(useContext(RouterContext), "no router");
export const useLocation = () => useRouter().location;

function createLocation(path) {
  const search = createMemo(() => path());
  return {
    get search() {
      return search();
    },
    get key() {
      return "";
    },
  };
}

export function createRouterState() {
  const [path] = createSignal("/");
  const location = createLocation(path);
  return {
    base: "/",
    location,
    get pending() {
      return false;
    },
  };
}
